import{_ as a,o as e,c as s,ae as n}from"./chunks/framework.1Lna8NcP.js";const u=JSON.parse('{"title":"Libertas — Personal Finance Dashboard","description":"","frontmatter":{},"headers":[],"relativePath":"adr/001-finance-dashboard-design.md","filePath":"adr/001-finance-dashboard-design.md"}'),i={name:"adr/001-finance-dashboard-design.md"};function r(o,t,d,l,c,p){return e(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="libertas-—-personal-finance-dashboard" tabindex="-1">Libertas — Personal Finance Dashboard <a class="header-anchor" href="#libertas-—-personal-finance-dashboard" aria-label="Permalink to &quot;Libertas — Personal Finance Dashboard&quot;">​</a></h1><p><strong>Design Spec | 2026-04-03</strong></p><hr><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The user has financial assets spread across many institutions: brokerage accounts, crypto exchanges, real estate properties, HSA, Roth IRA, savings, and more. No single tool gives a unified view without paying for a third-party service or handing over account credentials. Libertas is a locally-hosted personal finance dashboard that ingests exported CSV/Excel data from each institution, enriches it with free public price APIs, and presents a unified net worth view with insights, projections, and allocation breakdowns. No third-party services. No cloud. No account linking. All data stays on the user&#39;s machine.</p><p><strong>Privacy as a feature:</strong> The &quot;no data collection, locally-hosted&quot; nature is a genuine selling point — it&#39;s the kind of thing that convinces users to choose a tool. This should be front-and-center in the UI and docs, not buried.</p><p><strong>Manual refresh trade-off:</strong> The CSV export/import flow introduces friction compared to auto-syncing apps. This is an intentional trade-off for privacy. The UX should minimize this friction wherever possible — watch folder auto-detection, staleness indicators, and one-click institution export links are the primary mitigations already in the spec. Future iterations could explore read-only bank API integrations (Plaid-free) as an opt-in.</p><hr><h2 id="design-inspiration" tabindex="-1">Design Inspiration <a class="header-anchor" href="#design-inspiration" aria-label="Permalink to &quot;Design Inspiration&quot;">​</a></h2><p>Study these apps when designing the UI — both are praised for modern, non-generic aesthetics:</p><table tabindex="0"><thead><tr><th>App</th><th>Notes</th></tr></thead><tbody><tr><td><strong>Fey</strong> (fey.com)</td><td>Beautiful, clean portfolio UI. Reference for visual quality bar.</td></tr><tr><td><strong>Copilot Money</strong> (copilot.money)</td><td>Modern portfolio + budgeting app. More polished than typical SaaS.</td></tr></tbody></table><p>Both represent a design direction that&#39;s more refined than the generic SaaS aesthetic that dominated 2016–2024. Libertas should feel closer to these than to a typical dashboard tool.</p><hr><h2 id="stack" tabindex="-1">Stack <a class="header-anchor" href="#stack" aria-label="Permalink to &quot;Stack&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Technology</th></tr></thead><tbody><tr><td>Backend</td><td>Python 3.11+, FastAPI, SQLAlchemy, SQLite</td></tr><tr><td>Frontend</td><td>Vite + React 18 + TypeScript + Recharts</td></tr><tr><td>Docs</td><td>VitePress (Markdown), deployed to GitHub Pages</td></tr><tr><td>Stock prices</td><td><code>yfinance</code> (Yahoo Finance, no API key)</td></tr><tr><td>Crypto prices</td><td>CoinGecko REST API (free tier, no API key)</td></tr><tr><td>Real estate values</td><td><code>httpx</code> + <code>beautifulsoup4</code> scraping Zillow/Redfin, with manual override</td></tr><tr><td>Dev launcher</td><td>Single <code>start.sh</code> script (concurrently runs backend + frontend)</td></tr></tbody></table><hr><h2 id="project-structure" tabindex="-1">Project Structure <a class="header-anchor" href="#project-structure" aria-label="Permalink to &quot;Project Structure&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/Libertas</span></span>
<span class="line"><span>  /backend</span></span>
<span class="line"><span>    main.py               ← FastAPI app entrypoint, serves built frontend as static files</span></span>
<span class="line"><span>    database.py           ← SQLite setup via SQLAlchemy</span></span>
<span class="line"><span>    models.py             ← ORM table definitions</span></span>
<span class="line"><span>    /routers</span></span>
<span class="line"><span>      accounts.py         ← CRUD for accounts and institutions</span></span>
<span class="line"><span>      imports.py          ← CSV/Excel ingestion, column mapping, deduplication</span></span>
<span class="line"><span>      prices.py           ← stock + crypto price refresh</span></span>
<span class="line"><span>      real_estate.py      ← property CRUD, Zillow scraping, manual override</span></span>
<span class="line"><span>      projections.py      ← growth projection calculations</span></span>
<span class="line"><span>      snapshots.py        ← net worth snapshot recording</span></span>
<span class="line"><span>      insights.py         ← rule-based insight engine</span></span>
<span class="line"><span>      settings.py         ← app settings CRUD</span></span>
<span class="line"><span>    /watchers</span></span>
<span class="line"><span>      folder_watcher.py   ← watchdog-based watch folder monitor</span></span>
<span class="line"><span>    /importers</span></span>
<span class="line"><span>      base.py             ← abstract importer interface</span></span>
<span class="line"><span>      fidelity.py         ← Fidelity preset column mapping</span></span>
<span class="line"><span>      schwab.py</span></span>
<span class="line"><span>      coinbase.py</span></span>
<span class="line"><span>      robinhood.py</span></span>
<span class="line"><span>      generic.py          ← fallback auto-mapper for unknown institutions</span></span>
<span class="line"><span>  /frontend</span></span>
<span class="line"><span>    /src</span></span>
<span class="line"><span>      /components         ← reusable UI: charts, cards, tables, badges</span></span>
<span class="line"><span>      /pages</span></span>
<span class="line"><span>        Dashboard.tsx</span></span>
<span class="line"><span>        Accounts.tsx</span></span>
<span class="line"><span>        Import.tsx</span></span>
<span class="line"><span>        RealEstate.tsx</span></span>
<span class="line"><span>        Projections.tsx</span></span>
<span class="line"><span>        Insights.tsx</span></span>
<span class="line"><span>        Settings.tsx</span></span>
<span class="line"><span>      /api                ← typed fetch wrappers (one file per router)</span></span>
<span class="line"><span>      /types              ← shared TypeScript interfaces mirroring DB models</span></span>
<span class="line"><span>      /hooks              ← useAccounts, usePrices, useInsights, etc.</span></span>
<span class="line"><span>    vite.config.ts</span></span>
<span class="line"><span>    tsconfig.json</span></span>
<span class="line"><span>  /docs                   ← VitePress documentation site</span></span>
<span class="line"><span>    index.md</span></span>
<span class="line"><span>    /guide</span></span>
<span class="line"><span>      getting-started.md</span></span>
<span class="line"><span>      importing-data.md</span></span>
<span class="line"><span>      real-estate.md</span></span>
<span class="line"><span>      insights.md</span></span>
<span class="line"><span>      projections.md</span></span>
<span class="line"><span>    /reference</span></span>
<span class="line"><span>      accounts.md</span></span>
<span class="line"><span>      faq.md</span></span>
<span class="line"><span>    .vitepress/config.ts</span></span>
<span class="line"><span>  /data</span></span>
<span class="line"><span>    libertas.db           ← SQLite database (all user data)</span></span>
<span class="line"><span>    /watch                ← watched folder: drop exported CSVs here</span></span>
<span class="line"><span>  .github/workflows/</span></span>
<span class="line"><span>    docs.yml              ← builds VitePress and deploys to GitHub Pages</span></span>
<span class="line"><span>  start.sh                ← starts backend + frontend concurrently</span></span>
<span class="line"><span>  start-docs.sh           ← starts VitePress dev server for editing docs</span></span></code></pre></div><hr><h2 id="data-model" tabindex="-1">Data Model <a class="header-anchor" href="#data-model" aria-label="Permalink to &quot;Data Model&quot;">​</a></h2><h3 id="accounts" tabindex="-1"><code>accounts</code> <a class="header-anchor" href="#accounts" aria-label="Permalink to &quot;\`accounts\`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Column</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td>id</td><td>INTEGER PK</td><td></td></tr><tr><td>name</td><td>TEXT</td><td>User-defined label (e.g. &quot;Fidelity Roth IRA&quot;)</td></tr><tr><td>type</td><td>TEXT</td><td>brokerage | crypto | real_estate | savings | hsa | roth_ira | 401k | checking</td></tr><tr><td>institution_id</td><td>INTEGER FK</td><td>Links to institutions table</td></tr><tr><td>currency</td><td>TEXT</td><td>Default USD</td></tr><tr><td>created_at</td><td>DATETIME</td><td></td></tr></tbody></table><h3 id="institutions" tabindex="-1"><code>institutions</code> <a class="header-anchor" href="#institutions" aria-label="Permalink to &quot;\`institutions\`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Column</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td>id</td><td>INTEGER PK</td><td></td></tr><tr><td>name</td><td>TEXT</td><td>e.g. &quot;Fidelity&quot;, &quot;Coinbase&quot;</td></tr><tr><td>export_url</td><td>TEXT</td><td>Direct link to the export page on their website</td></tr><tr><td>file_pattern</td><td>TEXT</td><td>Glob pattern to auto-match files, e.g. <code>Fidelity_*.csv</code></td></tr><tr><td>column_mapping</td><td>JSON</td><td>Saved after first import: maps their headers to Libertas fields</td></tr><tr><td>importer_preset</td><td>TEXT</td><td>fidelity | schwab | coinbase | robinhood | generic</td></tr><tr><td>notes</td><td>TEXT</td><td>Optional user notes (e.g. &quot;Select &#39;All Accounts&#39; before exporting&quot;)</td></tr></tbody></table><h3 id="holdings" tabindex="-1"><code>holdings</code> <a class="header-anchor" href="#holdings" aria-label="Permalink to &quot;\`holdings\`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Column</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td>id</td><td>INTEGER PK</td><td></td></tr><tr><td>account_id</td><td>INTEGER FK</td><td></td></tr><tr><td>symbol</td><td>TEXT</td><td>Ticker or coin ID</td></tr><tr><td>quantity</td><td>REAL</td><td></td></tr><tr><td>cost_basis</td><td>REAL</td><td>Total cost basis</td></tr><tr><td>last_price</td><td>REAL</td><td>Updated via price refresh</td></tr><tr><td>last_updated</td><td>DATETIME</td><td></td></tr></tbody></table><h3 id="transactions" tabindex="-1"><code>transactions</code> <a class="header-anchor" href="#transactions" aria-label="Permalink to &quot;\`transactions\`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Column</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td>id</td><td>INTEGER PK</td><td></td></tr><tr><td>account_id</td><td>INTEGER FK</td><td></td></tr><tr><td>date</td><td>DATE</td><td></td></tr><tr><td>type</td><td>TEXT</td><td>buy | sell | deposit | withdrawal | dividend | transfer</td></tr><tr><td>symbol</td><td>TEXT</td><td>Nullable for cash transactions</td></tr><tr><td>quantity</td><td>REAL</td><td></td></tr><tr><td>price</td><td>REAL</td><td></td></tr><tr><td>amount</td><td>REAL</td><td>Total dollar value</td></tr><tr><td>description</td><td>TEXT</td><td></td></tr><tr><td>raw_row</td><td>JSON</td><td>Original CSV row, preserved for debugging</td></tr><tr><td>import_hash</td><td>TEXT</td><td>SHA256 of raw row for deduplication</td></tr></tbody></table><h3 id="balance-snapshots" tabindex="-1"><code>balance_snapshots</code> <a class="header-anchor" href="#balance-snapshots" aria-label="Permalink to &quot;\`balance_snapshots\`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Column</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td>id</td><td>INTEGER PK</td><td></td></tr><tr><td>account_id</td><td>INTEGER FK</td><td></td></tr><tr><td>date</td><td>DATE</td><td></td></tr><tr><td>balance</td><td>REAL</td><td>Point-in-time balance in USD</td></tr></tbody></table><h3 id="real-estate" tabindex="-1"><code>real_estate</code> <a class="header-anchor" href="#real-estate" aria-label="Permalink to &quot;\`real_estate\`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Column</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td>id</td><td>INTEGER PK</td><td></td></tr><tr><td>account_id</td><td>INTEGER FK</td><td></td></tr><tr><td>address</td><td>TEXT</td><td></td></tr><tr><td>purchase_price</td><td>REAL</td><td></td></tr><tr><td>purchase_date</td><td>DATE</td><td></td></tr><tr><td>zillow_estimate</td><td>REAL</td><td>Last scraped value</td></tr><tr><td>manual_override</td><td>REAL</td><td>If set, used instead of Zillow estimate</td></tr><tr><td>effective_value</td><td>REAL</td><td>Computed: manual_override ?? zillow_estimate</td></tr><tr><td>mortgage_balance</td><td>REAL</td><td></td></tr><tr><td>last_updated</td><td>DATETIME</td><td></td></tr></tbody></table><h3 id="settings" tabindex="-1"><code>settings</code> <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;\`settings\`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Column</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td>key</td><td>TEXT PK</td><td></td></tr><tr><td>value</td><td>TEXT</td><td>JSON-serialized</td></tr></tbody></table><p>Settings keys: <code>monthly_expenses</code>, <code>risk_profile</code>, <code>claude_api_key</code>, <code>watch_folder_path</code>, <code>projection_return_rates</code></p><hr><h2 id="pages-screens" tabindex="-1">Pages &amp; Screens <a class="header-anchor" href="#pages-screens" aria-label="Permalink to &quot;Pages &amp; Screens&quot;">​</a></h2><h3 id="dashboard" tabindex="-1">Dashboard <a class="header-anchor" href="#dashboard" aria-label="Permalink to &quot;Dashboard&quot;">​</a></h3><ul><li>Total net worth (large hero number, delta since last snapshot)</li><li>Asset allocation donut chart: stocks / crypto / real estate / cash / HSA / retirement</li><li>Net worth over time line chart (monthly balance snapshots)</li><li>Top movers today (gainers and losers across all holdings)</li><li>Account balance cards with staleness indicator (green &lt; 3 days, yellow 3-7 days, red &gt; 7 days)</li></ul><h3 id="accounts-1" tabindex="-1">Accounts <a class="header-anchor" href="#accounts-1" aria-label="Permalink to &quot;Accounts&quot;">​</a></h3><ul><li>List all accounts with current balance, type badge, last updated</li><li>Click into account → transaction history table, holdings breakdown, performance chart</li></ul><h3 id="import" tabindex="-1">Import <a class="header-anchor" href="#import" aria-label="Permalink to &quot;Import&quot;">​</a></h3><ul><li>Drag-and-drop zone for CSV/Excel (or auto-picked up from watch folder)</li><li>Institution selector — shows all saved institutions with their one-click export links</li><li>&quot;Add new institution&quot; flow: name, export URL, paste a sample CSV to teach column mapping</li><li>Auto column-mapping preview with correction UI before confirm</li><li>Import history log with row counts and timestamps</li></ul><h3 id="real-estate-1" tabindex="-1">Real Estate <a class="header-anchor" href="#real-estate-1" aria-label="Permalink to &quot;Real Estate&quot;">​</a></h3><ul><li>Property cards: address, current value, mortgage balance, equity, LTV percentage</li><li>Add/edit property form</li><li>Equity over time chart per property</li><li>Zillow/Redfin auto-refresh with &quot;Override value&quot; field that takes precedence</li></ul><h3 id="projections" tabindex="-1">Projections <a class="header-anchor" href="#projections" aria-label="Permalink to &quot;Projections&quot;">​</a></h3><ul><li>Configure: annual return rate, monthly contribution, time horizon (years)</li><li>Three scenario curves: conservative (4%), moderate (7%), aggressive (10%)</li><li>Total projected value by year, broken down by account type</li><li>Assumes current balances as starting point</li></ul><h3 id="insights" tabindex="-1">Insights <a class="header-anchor" href="#insights" aria-label="Permalink to &quot;Insights&quot;">​</a></h3><ul><li>Card grid, one card per insight</li><li>Color-coded categories: Risk / Performance / Tax Efficiency / Liquidity / Trends</li><li>Each card: title, plain-English explanation, &quot;Why this matters&quot; line</li><li>Insight categories: <ul><li><strong>Concentration:</strong> single-stock or single-asset overweight</li><li><strong>Allocation:</strong> deviation from target mix by risk profile</li><li><strong>Performance vs benchmarks:</strong> YTD vs S&amp;P 500, BTC benchmark for crypto</li><li><strong>Liquidity:</strong> months of expenses in liquid accounts</li><li><strong>Real estate:</strong> LTV, equity growth rate, refinance opportunity signals</li><li><strong>Tax efficiency:</strong> asset placement (bonds in taxable, growth in Roth, etc.)</li><li><strong>Trends:</strong> net worth growth rate change, accelerating/decelerating savings</li></ul></li><li>Optional Claude API chat at bottom: ask questions about your finances in natural language (opt-in, requires API key in Settings)</li></ul><h3 id="settings-1" tabindex="-1">Settings <a class="header-anchor" href="#settings-1" aria-label="Permalink to &quot;Settings&quot;">​</a></h3><ul><li>Manage institutions: add, edit export URL, view/reset column mapping</li><li>Manage accounts: add, rename, delete, assign institution</li><li>Watch folder path configuration</li><li>Monthly expenses (used for liquidity calculations)</li><li>Risk profile selector (conservative / moderate / aggressive)</li><li>Claude API key (optional, for Insights chat)</li><li>Export all data as JSON backup</li><li>Manual &quot;Refresh prices&quot; button</li></ul><hr><h2 id="data-refresh-flow" tabindex="-1">Data Refresh Flow <a class="header-anchor" href="#data-refresh-flow" aria-label="Permalink to &quot;Data Refresh Flow&quot;">​</a></h2><ol><li>User opens dashboard — staleness indicators show which accounts need updating (color-coded)</li><li>User clicks account card → one-click button opens the institution&#39;s export URL directly in browser</li><li>User logs in, navigates to export, downloads CSV, saves to the watch folder (<code>/data/watch/</code>)</li><li>App detects new file via folder watcher → matches to institution by filename pattern</li><li>Auto-maps columns using saved mapping (no user action needed after first import)</li><li>Shows preview toast: &quot;Detected 143 new transactions from Fidelity — Import?&quot; → one click confirm</li><li>Transactions deduplicated by hash → holdings and balance snapshot updated</li><li>Prices refreshed via yfinance/CoinGecko → net worth recalculated → insights re-run</li></ol><hr><h2 id="csv-ingestion-detail" tabindex="-1">CSV Ingestion Detail <a class="header-anchor" href="#csv-ingestion-detail" aria-label="Permalink to &quot;CSV Ingestion Detail&quot;">​</a></h2><p><strong>First-time import for a new institution:</strong></p><ol><li>User uploads file and selects or creates an institution</li><li>Backend inspects headers + 3 sample rows, scores each header against known field types</li><li>Presents mapping table: their column → Libertas field (editable)</li><li>User confirms → mapping saved to <code>institutions.column_mapping</code></li><li>Data imported, import_hash stored per row for future deduplication</li></ol><p><strong>Subsequent imports:</strong></p><ul><li>Saved mapping applied automatically</li><li>Only new rows (by import_hash) are inserted</li><li>Re-importing the same file is always safe</li></ul><p><strong>Built-in presets (zero-config on first import):</strong> Fidelity, Schwab, Robinhood, Coinbase, Chase, Vanguard</p><hr><h2 id="documentation-site" tabindex="-1">Documentation Site <a class="header-anchor" href="#documentation-site" aria-label="Permalink to &quot;Documentation Site&quot;">​</a></h2><p>VitePress in <code>/docs</code>, deployed to GitHub Pages via GitHub Actions on every push to <code>main</code>.</p><p><strong>Public URL:</strong> <code>https://&lt;username&gt;.github.io/libertas</code></p><p>Only the compiled static docs are deployed — no app code, no data, no SQLite file is ever exposed.</p><p><strong>Structure:</strong></p><ul><li>Landing page with feature overview</li><li>Getting Started: install, first run, adding your first account</li><li>Importing Data: step-by-step per institution type, watch folder setup</li><li>Real Estate: adding properties, Zillow estimates, manual override</li><li>Insights: what each insight type means and how to act on it</li><li>Projections: how scenarios are calculated</li><li>Reference: account types, FAQ</li></ul><p>Docs are Markdown files in <code>/docs</code>. Updating docs = editing a <code>.md</code> file and pushing. No separate deploy step needed.</p><hr><h2 id="startup" tabindex="-1">Startup <a class="header-anchor" href="#startup" aria-label="Permalink to &quot;Startup&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./start.sh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # starts FastAPI (port 8000) + Vite dev server (port 5173) concurrently</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./start-docs.sh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # starts VitePress dev server for editing docs locally</span></span></code></pre></div><p>For daily use after building: <code>npm run build --prefix frontend</code> once, then only <code>./start.sh</code> needed — FastAPI serves the compiled frontend at <code>localhost:8000</code>.</p><hr><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><ul><li><code>localhost:8000</code> serves the dashboard</li><li>Drop a sample CSV into <code>/data/watch/</code> → toast appears within 2 seconds</li><li>Import confirms → transaction count increases in Accounts page</li><li>Dashboard net worth updates to reflect new balances</li><li>Insights tab shows at least one card after data is populated</li><li>Projections page renders three scenario curves</li><li><code>https://&lt;username&gt;.github.io/libertas</code> renders VitePress docs after first push to <code>main</code></li></ul>`,76)])])}const b=a(i,[["render",r]]);export{u as __pageData,b as default};
